INSERT INTO `playerchoice_response_locale` (`ChoiceId`, `ResponseId`, `locale`, `Header`, `Answer`, `Description`, `Confirmation`) VALUES
(255, 546, 'frFR', 'Dévastation', 'Choisir', 'Ces glaives appartenaient à l’ancien chasseur de démons Varedis Gangrâme, tombé en défendant le Temple noir il y a bien des années.\n\nLe maître de la Légion ardente, Kil’jaeden le Trompeur, a ramené Varedis à la vie dans le Néant distordu et a imprégné ses glaives d’une part de son pouvoir chaotique.', ''),
(255, 547, 'frFR', 'Vengeance', 'Choisir', 'Les puissants Aldrachi furent parmi les rares à tenir tête à la Légion ardente. Il fallut Sargeras en personne pour abattre leur plus grand champion et s’emparer de ses lames de guerre.\n\nAujourd’hui, la traîtresse illidari Caria, servante de Kil’jaeden, manie ces lames de sinistre réputation. Plus elle prend d’âmes, plus elle gagne en puissance…', '');

