UPDATE `playerchoice_response` SET `Header` = 'Assassination', `Answer` = 'Select', `Confirmation` = 'CONFIRM_ARTIFACT_CHOICE', `Description` = 'The Kingslayers are the daggers of Garona, with which she slew the treacherous Gul\'dan. They leave a poison that cannot be traced, so when the Kingslayers decide someone\'s fate, nothing can ever be proven.\n\nHer tormented mind drove Garona to hide the daggers, but she later went back for them to fight the dangerous servants of the Legion.\n\nWe have to find her.' WHERE `ChoiceId` = 262 AND `ResponseId` = 568;
UPDATE `playerchoice_response` SET `Header` = 'Outlaw', `Answer` = 'Select', `Confirmation` = 'CONFIRM_ARTIFACT_CHOICE', `Description` = 'The dread admiral Eliza is the terror of the South Seas. Her cursed blades strike fear into many.\n\nWe have learned that her ship has dropped anchor off the coast of Azsuna, on the Broken Isles. If you hurry, you can claim her blades.' WHERE `ChoiceId` = 262 AND `ResponseId` = 569;
UPDATE `playerchoice_response` SET `Header` = 'Subtlety', `Answer` = 'Select', `Confirmation` = 'CONFIRM_ARTIFACT_CHOICE', `Description` = 'Akaari Shadowgore is an unrivaled eredar assassin and the pride of the Legion. Her daggers can bend space itself, hiding their wielder in the shadows.\n\nOur intelligence tells us where she is right now. It is time to strike.' WHERE `ChoiceId` = 262 AND `ResponseId` = 570;
