DELETE FROM `playerchoice_response_locale` WHERE `locale` = 'frFR' AND `ChoiceId` IN (231, 234, 235, 236, 240, 242, 245, 247, 248, 253, 255, 262, 265, 266, 270, 273, 274, 275, 277, 279, 280, 282, 284, 287, 288, 292);
INSERT INTO `playerchoice_response_locale` (`ChoiceId`, `ResponseId`, `locale`, `Header`, `Answer`, `Description`, `Confirmation`) VALUES
(235, 488, 'frFR', 'Sacré', 'Choisir', 'Un ordre secret de paladins veille depuis des siècles sur le lieu de repos du grand gardien titanesque Tyr. Les chroniques racontent que son puissant marteau de guerre fut enterré avec lui.\n\nDes événements récents ont menacé la sécurité de ce secret, et l’ordre a appelé à l’aide les paladins de tout Azeroth.', ''),
(235, 489, 'frFR', 'Protection', 'Choisir', 'Une ancienne saga vrykul parle d’un bouclier forgé par Tyr lui-même. Pendant la guerre de Hiverskorn, il servit à révéler aux vrykuls les mensonges de Loken et rallia nombre d’entre eux à la cause de Tyr.\n\nLe lieu où repose ce bouclier s’est perdu avec le temps, mais la rumeur désigne quelqu’un qui connaîtrait les derniers chapitres de son histoire.', ''),
(235, 490, 'frFR', 'Vindicte', 'Choisir', 'Lors de notre assaut manqué sur le rivage Brisé, le généralissime Tirion Fordring a disparu, et avec lui notre plus grande arme contre la Légion : le Porte-cendres.\n\nNous devons retourner sur le rivage Brisé et retrouver Tirion et le Porte-cendres à tout prix.', ''),
(236, 491, 'frFR', 'Armes', 'Choisir', 'Thoradin, premier roi des humains, était un souverain puissant et un redoutable guerrier. Il portait une grande épée forgée par les vrykuls, renforcée par les elfes et ensanglantée sur d’innombrables champs de bataille.\n\nStrom’kar, celle qui met fin aux guerres, a disparu avec Thoradin. Qui serait assez fort pour la reprendre manierait une lame comme on n’en a plus vu depuis des siècles.', ''),
(236, 492, 'frFR', 'Protection', 'Choisir', 'Un ancien roi vrykul fit d’une écaille volée à Neltharion, le Gardien de la terre, un rempart d’une puissance immense. Ce grand bouclier repose aujourd’hui à ses côtés, au fond d’un tombeau presque oublié.\n\nReprenez ce bouclier et vous gagnerez non seulement une garde impénétrable, mais aussi un aperçu des puissants pouvoirs ardents de l’Aspect dragon lui-même.', ''),
(236, 493, 'frFR', 'Fureur', 'Choisir', 'Les épées de guerre de mon propre Valarjar, mon plus grand champion, m’ont été volées par cette chienne de Helya. Elle et son serviteur idiot se moquent de leur valeur en volant les âmes des grands héros avant qu’ils puissent monter aux salles des Valeureux.\n\nDe puissantes armes qui feraient de vous une tempête vivante d’acier et de feu. Elles feraient un choix digne de vous.', ''),
(240, 504, 'frFR', 'Maîtrise des bêtes', 'Choisir', 'Dans les temps anciens, un seigneur de guerre vrykul a volé un fusil imprégné de la puissance des tempêtes. Il se servit de la force de l’artefact pour soumettre ses rivaux sur les îles Brisées.\n\nDescendez dans le tombeau du seigneur de guerre et reprenez cette arme redoutable !', ''),
(240, 505, 'frFR', 'Survie', 'Choisir', 'La tribu de Haut-Roc a perdu sa plus grande arme, l’antique lance de Huln Haut-Roc, il y a bien longtemps, au profit d’une monstruosité corrompue par la magie.\n\nElle vous demande de vous rendre à Tornheim, de tuer son ennemi juré et de reprendre la lance pour le combat contre la Légion.', ''),
(240, 506, 'frFR', 'Précision', 'Choisir', 'Il y a bien des années, la forestière Alleria Coursevent maniait l’arc de sa famille, Thas’dorah, pour combattre la Légion. On ignore où elle se trouve aujourd’hui.\n\nSi l’on retrouvait Alleria, son arme deviendrait un atout précieux dans la guerre contre les démons.', ''),
(242, 511, 'frFR', 'Maître brasseur', 'Choisir', 'Chen Brune d’Orage est parti pour le rivage Brisé et nous n’avons plus de nouvelles de lui.\n\nSon bâton est une arme puissante qui appartint jadis au Roi-singe. S’il est tombé, nous ne pouvons pas laisser la Légion s’en emparer !', ''),
(242, 512, 'frFR', 'Tisse-brume', 'Choisir', 'Il y a bien longtemps, le dernier empereur pandaren se servit de son bâton, Sheilun, pour envelopper toute la Pandarie de brumes.\n\nLe bâton est resté pendant des générations sur la terrasse du Printemps éternel. Quand la Légion a attaqué la Pandarie, les défenseurs pandashan se sont précipités pour protéger les lieux. Nous n’avons plus de nouvelles d’eux et nous craignons le pire : le bâton ne doit pas tomber entre de mauvaises mains !', ''),
(242, 513, 'frFR', 'Marche-vent', 'Choisir', 'Des voyageurs revenus de l’étranger ont répandu un curieux récit sur l’île. Ils parlent d’une paire de lames de poing antiques qui, selon la légende, conféraient à leur porteur le pouvoir de la tempête.\n\nOn sait peu de choses de cette arme mystérieuse, mais si ses pouvoirs sont réels, nous devrions envisager de la chercher.', ''),
(245, 523, 'frFR', 'Affliction', 'Choisir', 'Maniée par Sataiel, la première nécrolyte, la Faucheuse de Deuillevent doit son nom à la vie qu’elle arracha aux terres du défilé de Deuillevent.\n\nAprès des siècles sous clé, Ulthalesh a été retrouvée entre les mains des Cavaliers noirs. Vous devez les traquer si vous voulez savoir où ils la cachent.', ''),
(245, 524, 'frFR', 'Démonologie', 'Choisir', 'Le sorcier Thal’kiel fut l’un des premiers érédars à apprendre l’art d’invoquer et de soumettre les démons.\n\nAprès sa défaite, son crâne fut exposé pour rappeler les dangers des arts obscurs. La leçon ne fut pas retenue.\n\nAprès la chute des érédars, les généraux de la Légion ardente s’emparèrent du crâne pour mieux tenir leurs armées.', ''),
(245, 525, 'frFR', 'Destruction', 'Choisir', 'Façonné par des centaines de démonistes érédars et par le titan noir lui-même, ce sceptre a servi à de terribles actes de destruction. Capable d’ouvrir des brèches dans la réalité vers d’autres mondes, il fut la clé de l’invasion d’Azeroth.\n\nNer’zhul l’utilisa plus tard et libéra sans réfléchir sa puissance sur Draenor, qui faillit en être anéanti. On le croyait perdu depuis longtemps, mais il est revenu entre les mains de la Légion.', ''),
(247, 529, 'frFR', 'Équilibre', 'Choisir', 'Gardée en lieu sûr par Tyrande, la grande prêtresse d’Élune, la Faux d’Élune a une histoire longue et troublante aux yeux des druides.\n\nLiée à l’apparition des worgens sur Azeroth, on dit qu’elle recèle une puissance lunaire inouïe pour le druide assez équilibré pour la maîtriser.\n\nIl nous suffit de convaincre le peuple de Tyrande que vous êtes digne de la protéger dans les batailles à venir.', ''),
(247, 530, 'frFR', 'Farouche', 'Choisir', 'Ashamane, une sabre-de-nuit antique et puissante, combattit pendant la guerre des Anciens et tomba il y a des siècles au cœur des forêts de Val’sharah.\n\nUn groupe de druides, les Cendrés, honore sa mémoire et garde le sanctuaire qui abrite ses crocs.\n\nIl faudra les persuader de laisser leur précieux artefact servir au combat, mais ses crocs seraient une arme redoutable contre la Légion.', ''),
(247, 531, 'frFR', 'Gardien', 'Choisir', 'Le puissant dieu ours Ursoc mourut pendant la guerre des Anciens en défendant Azeroth contre la Légion ardente.\n\nLes derniers vestiges de son corps, ses griffes, furent placés dans le Rêve d’émeraude pour être protégés. Son esprit veille toujours sur elles.\n\nSi vous parvenez à obtenir les griffes, elles seraient un atout précieux dans nos combats contre la Légion.', ''),
(247, 545, 'frFR', 'Restauration', 'Choisir', 'Il y a des milliers d’années, Aviana offrit aux premiers druides une branche de l’Arbre-Mère, G’Hanir.\n\nOn dit que ce bâton aide son porteur à atteindre une parfaite harmonie avec la nature et à puiser dans des sorts de soins d’une grande puissance.\n\nLa branche est gardée dans un sanctuaire sous les racines de Shaladrassil, mais nous avons récemment perdu le contact avec les druides qui s’y trouvent…', ''),
(248, 532, 'frFR', 'Sacré', 'Choisir', 'Les draeneï ont dû fuir de nombreux mondes, pourchassés par la Légion à travers les cieux. Sur l’un d’eux, quelques braves sont restés avec le joyau de guérison radieux, T’uure, pour affronter la Légion et permettre aux leurs de s’échapper.\n\nUne rumeur dit qu’un soldat de Dalaran a vu le cristal perdu entre les mains de la Légion. Si c’est vrai, il faut le récupérer !', ''),
(248, 533, 'frFR', 'Ombre', 'Choisir', 'Une antique dague des Dieux très anciens a refait surface pour rendre sa puissance au Marteau du crépuscule. Ses membres accomplissent tout près un rituel impie qu’il faut arrêter.\n\nLa lame de l’Empire noir est une puissante dague sacrificielle accordée au Vide, utilisée depuis des temps immémoriaux dans d’horribles rites voués aux Dieux très anciens. Elle emplit son porteur d’une puissante énergie d’ombre et d’attaques mentales.', ''),
(248, 534, 'frFR', 'Discipline', 'Choisir', 'Obsédée par l’idée de purger Azeroth des morts-vivants, la fanatique Croisade écarlate tenta de créer un second Porte-cendres sous la forme d’un bâton. Mais une trahison interne fit échouer le rituel dans une grande explosion de flammes. La puissance du bâton endommagé se révéla presque impossible à maîtriser.\n\nCraignant son pouvoir destructeur, les mages d’élite du Kirin Tor le mirent hors de portée des mortels.', ''),
(253, 541, 'frFR', 'Sang', 'Choisir', 'Gorelix l’Écorcheur est un monstrueux guerrier démon. Avec sa hache gigantesque, la Gueule des Damnés, il a ravagé à lui seul des mondes entiers.\n\nLa Gueule des Damnés permet à son porteur de sacrifier son propre sang pour nourrir sa magie noire et renforcer ses défenses.', ''),
(253, 542, 'frFR', 'Givre', 'Choisir', 'Même quatre ans après sa destruction dans la citadelle de la Couronne de glace, la légendaire Deuillegivre reste l’une des armes les plus tristement célèbres d’Azeroth.\n\nAvec un peu de puissance nécromantique, ses fragments brisés pourraient être reforgés en une paire de lames runiques aussi puissantes que leur aînée.', ''),
(253, 543, 'frFR', 'Impie', 'Choisir', 'Lame antique forgée par les nathrezim, Apocalypse sème la peste, la mort et la violence sur son passage. C’est un puissant instrument de destruction.\n\nElle était entre les mains de la Tirisgarde avant de tomber entre celles des Cavaliers noirs. Le seul moyen de la retrouver est de traquer les cavaliers jusqu’à leur repaire secret.\n\nApocalypse confère à son porteur de puissantes attaques de magie d’ombre et de redoutables serviteurs.', ''),
(255, 546, 'frFR', 'Dévastation', 'Choisir', 'Ces glaives appartenaient à l’ancien chasseur de démons Varedis Gangrâme, tombé en défendant le Temple noir il y a bien des années.\n\nLe maître de la Légion ardente, Kil’jaeden le Trompeur, a ramené Varedis à la vie dans le Néant distordu et a imprégné ses glaives d’une part de son pouvoir chaotique.', ''),
(255, 547, 'frFR', 'Vengeance', 'Choisir', 'Les puissants Aldrachi furent parmi les rares à tenir tête à la Légion ardente. Il fallut Sargeras en personne pour abattre leur plus grand champion et s’emparer de ses lames de guerre.\n\nAujourd’hui, la traîtresse illidari Caria, servante de Kil’jaeden, manie ces lames de sinistre réputation. Plus elle prend d’âmes, plus elle gagne en puissance…', ''),
(262, 568, 'frFR', 'Assassinat', 'Choisir', 'Les Régicides sont les dagues de Garona, celles avec lesquelles elle tua le perfide Gul’dan. Elles laissent un poison introuvable : quand les Régicides scellent le destin de quelqu’un, rien ne peut jamais être prouvé.\n\nSon esprit tourmenté poussa Garona à cacher les dagues, mais elle revint les chercher pour combattre les dangereux serviteurs de la Légion.\n\nNous devons la retrouver.', ''),
(262, 569, 'frFR', 'Hors-la-loi', 'Choisir', 'La terrible amirale Eliza est la terreur des mers du Sud. Ses lames maudites en effraient plus d’un.\n\nNous avons appris que son navire a jeté l’ancre au large d’Azsuna, sur les îles Brisées. Si vous faites vite, vous pourrez vous emparer de ses lames.', ''),
(262, 570, 'frFR', 'Finesse', 'Choisir', 'Akaari Gore-d’ombre est une assassine érédar sans égale, la fierté de la Légion. Ses dagues peuvent tordre l’espace lui-même et cacher leur porteur dans l’ombre.\n\nNos renseignements nous disent où elle se trouve en ce moment. Il est temps de frapper.', ''),
(265, 584, 'frFR', 'Arcanes', 'Choisir', 'Aluneth fut surtout maniée un temps par Aegwynn, la seule femme Gardienne de Tirisfal, bien que les récits la disent bien plus ancienne qu’elle.\n\nVers la fin de sa vie, Aegwynn confia le bâton au Vol bleu. Le jugeant trop dangereux, les dragons l’enfermèrent dans une chambre forte secrète, où il se trouve encore.', ''),
(265, 585, 'frFR', 'Feu', 'Choisir', '« Frappe-flamme » dans sa langue d’origine, Felo’melorn fut portée au combat par les membres de la famille Haut-Soleil quand ils prouvèrent leur valeur pendant la guerre des Anciens, les guerres des Trolls et contre le chevalier de la mort Arthas Menethil.\n\nL’épée finit par se perdre dans les étendues glacées du Norfendre.', ''),
(265, 586, 'frFR', 'Givre', 'Choisir', 'Ce grand bâton fut manié par Alodi, le premier Gardien de Tirisfal. Il le porta dans de nombreuses batailles contre les forces de la Légion pendant le siècle où il fut Gardien.\n\nPeu après avoir renoncé à sa charge, Alodi disparut avec le bâton. Nul ne sait où ils ont fini, sauf peut-être Alodi lui-même.', ''),
(266, 587, 'frFR', 'Amélioration', 'Choisir', 'Le Marteau-du-destin est tombé dans le Maelström. Il serait sage d’empêcher qu’il ne tombe entre de mauvaises mains.\n\nRendez-vous avec Thrall au Tréfonds pour retrouver l’artefact disparu. Prenez garde : le démon Geth’xun est lui aussi tombé dans le Maelström et pourrait être encore en vie.', ''),
(266, 588, 'frFR', 'Élémentaire', 'Choisir', 'Le gladiateur Rehgar connaît une arme puissante qui pourrait nous aider contre la Légion.\n\nAprès la campagne de Pandarie, les armes du dieu de la tempête Ra-den furent découvertes sous le trône du Tonnerre. Elles furent confiées au Tigre blanc, qui ne les remettra qu’à quelqu’un de digne. Rehgar vous aidera à prouver votre valeur !', ''),
(266, 589, 'frFR', 'Restauration', 'Choisir', 'On dit que la reine Azshara maniait un sceptre qui commandait aux mers et aux eaux de la vie.\n\nErunak cherche depuis longtemps où se trouve cet artefact, et l’une de ses chamanes était sur le point de le trouver quand elle a disparu. L’a-t-elle trouvé ? Les légendes seraient-elles vraies ? Que pourrait faire un tel artefact entre les mains d’un chaman talentueux ?', ''),
(270, 594, 'frFR', 'Arcanes', 'Choisir', 'Aluneth fut surtout maniée un temps par Aegwynn, la seule femme Gardienne de Tirisfal, bien que les récits la disent bien plus ancienne qu’elle.\n\nVers la fin de sa vie, Aegwynn confia le bâton au Vol bleu. Le jugeant trop dangereux, les dragons l’enfermèrent dans une chambre forte secrète, où il se trouve encore.', ''),
(270, 595, 'frFR', 'Feu', 'Choisir', '« Frappe-flamme » dans sa langue d’origine, Felo’melorn fut portée au combat par les membres de la famille Haut-Soleil quand ils prouvèrent leur valeur pendant la guerre des Anciens, les guerres des Trolls et contre le chevalier de la mort Arthas Menethil.\n\nL’épée finit par se perdre dans les étendues glacées du Norfendre.', ''),
(273, 598, 'frFR', 'Sacré', 'Choisir', 'Les draeneï ont dû fuir de nombreux mondes, pourchassés par la Légion à travers les cieux. Sur l’un d’eux, quelques braves sont restés avec le joyau de guérison radieux, T’uure, pour affronter la Légion et permettre aux leurs de s’échapper.\n\nUne rumeur dit qu’un soldat de Dalaran a vu le cristal perdu entre les mains de la Légion. Si c’est vrai, il faut le récupérer !', ''),
